worker_thread_ = std::thread([this, callback_fun, interval]() {
    for (;;) {
        std::unique_lock<std::mutex> lock(this->mutex_);
        if (this->cv_.wait_for(lock, interval, [this] { return !this->active_; })) {
            return;  // active_ == false, so exit this thread
        }
        callback_fun();
    }
});
